    const curriedVol = curry(volume);
    assertEqual(curriedVol(2)(3)(4), 24);
    assertEqual(curriedVol(2, 3)(4), 24);
    assertEqual(curriedVol(2)(3, 4), 24);
});

await test('Preserves context on final execution', () => {
    const multiplier = {
        factor: 10,
