function bindAll(obj, ...methodNames) {
  const methods = methodNames.length > 0
    ? methodNames
    : Object.keys(obj).filter(k => typeof obj[k] === 'function');

  for (const m of methods) {
    if (typeof obj[m] === 'function') {
      obj[m] = obj[m].bind(obj);
    }
  }
  return obj;
}

